package java.text;
import java.math.BigDecimal;import java.math.RoundingMode;import java.util.Locale;
public class DecimalFormat extends NumberFormat {
 private DecimalFormatSymbols symbols;private RoundingMode rounding=RoundingMode.HALF_EVEN;private String prefix="",suffix="";private int groupSize=3,multiplier=1,expDigits=0;private boolean scientific;
 public DecimalFormat(){this("#,##0.###");}public DecimalFormat(String p){this(p,new DecimalFormatSymbols());}public DecimalFormat(String p,DecimalFormatSymbols s){symbols=s;applyPattern(p);}
 public void applyPattern(String pattern){int semi=pattern.indexOf(';');if(semi>=0)pattern=pattern.substring(0,semi);int start=0;while(start<pattern.length()&&pattern.charAt(start)!='#'&&pattern.charAt(start)!='0')start++;int end=start;while(end<pattern.length()){char c=pattern.charAt(end);if(c!='#'&&c!='0'&&c!=','&&c!='.'&&c!='E')break;end++;}prefix=affix(pattern.substring(0,start));suffix=affix(pattern.substring(end));multiplier=pattern.indexOf('%')>=0?100:1;String body=pattern.substring(start,end);int e=body.indexOf('E');scientific=e>=0;expDigits=0;if(scientific){for(int i=e+1;i<body.length();i++)if(body.charAt(i)=='0')expDigits++;body=body.substring(0,e);}int dot=body.indexOf('.');String ip=dot<0?body:body.substring(0,dot),fp=dot<0?"":body.substring(dot+1);minInt=0;for(int i=0;i<ip.length();i++)if(ip.charAt(i)=='0')minInt++;minFrac=maxFrac=0;for(int i=0;i<fp.length();i++){if(fp.charAt(i)=='0')minFrac++;if(fp.charAt(i)=='0'||fp.charAt(i)=='#')maxFrac++;}int comma=ip.lastIndexOf(',');grouping=comma>=0;if(grouping)groupSize=ip.length()-comma-1;}
 private String affix(String x){return x.replace("¤",symbols.getCurrencySymbol()).replace("'","");}
 public void setRoundingMode(RoundingMode r){if(r==null)throw new NullPointerException();rounding=r;}public RoundingMode getRoundingMode(){return rounding;}public DecimalFormatSymbols getDecimalFormatSymbols(){return symbols;}public void setDecimalFormatSymbols(DecimalFormatSymbols s){symbols=s;}
 public StringBuffer format(long v,StringBuffer b,FieldPosition p){return render(new BigDecimal(v),false,b);}public StringBuffer format(double v,StringBuffer b,FieldPosition p){boolean neg=Double.doubleToRawLongBits(v)<0;if(Double.isNaN(v))return b.append(symbols.getNaN());if(Double.isInfinite(v))return b.append(neg?"-":"").append(prefix).append(symbols.getInfinity()).append(suffix);return render(BigDecimal.valueOf(v),neg,b);}
 private StringBuffer render(BigDecimal v,boolean negativeZero,StringBuffer out){boolean neg=v.signum()<0||negativeZero;v=v.abs().multiply(BigDecimal.valueOf(multiplier));int exponent=0;if(scientific&&v.signum()!=0){exponent=v.precision()-v.scale()-1;v=v.scaleByPowerOfTen(-exponent);}v=v.setScale(maxFrac,rounding);if(scientific&&v.compareTo(BigDecimal.TEN)>=0){v=v.scaleByPowerOfTen(-1);exponent++;}String d=v.toPlainString();int dot=d.indexOf('.');String ip=dot<0?d:d.substring(0,dot),fp=dot<0?"":d.substring(dot+1);while(fp.length()>minFrac&&fp.endsWith("0"))fp=fp.substring(0,fp.length()-1);while(ip.length()<minInt)ip="0"+ip;if(neg)out.append(symbols.getMinusSign());out.append(prefix);for(int i=0;i<ip.length();i++){if(grouping&&i>0&&(ip.length()-i)%groupSize==0)out.append(symbols.getGroupingSeparator());out.append(ip.charAt(i));}if(fp.length()>0)out.append(symbols.getDecimalSeparator()).append(fp);if(scientific){out.append('E');if(exponent<0){out.append('-');exponent=-exponent;}String es=Integer.toString(exponent);for(int i=es.length();i<expDigits;i++)out.append('0');out.append(es);}return out.append(suffix);}
 public Number parse(String s,ParsePosition pos){int start=pos.getIndex(),i=start;boolean neg=false;if(i<s.length()&&s.charAt(i)=='-'){neg=true;i++;}if(!s.startsWith(prefix,i)){pos.setErrorIndex(i);return null;}i+=prefix.length();StringBuilder d=new StringBuilder();boolean decimal=false,any=false;while(i<s.length()){char c=s.charAt(i);if(c>='0'&&c<='9'){d.append(c);any=true;i++;}else if(c==symbols.getGroupingSeparator()&&grouping)i++;else if(c==symbols.getDecimalSeparator()&&!decimal){decimal=true;d.append('.');i++;}else break;}if(any && i<s.length() && s.charAt(i)=='E'){int e=i+1;if(e<s.length() && s.charAt(e)=='-')e++;int first=e;while(e<s.length() && s.charAt(e)>='0' && s.charAt(e)<='9')e++;if(e>first){d.append(s.substring(i,e));i=e;}}if(!any||!s.startsWith(suffix,i)){pos.setErrorIndex(i);return null;}i+=suffix.length();pos.setIndex(i);BigDecimal v=new BigDecimal((neg?"-":"")+d.toString());if(multiplier!=1)v=v.divide(BigDecimal.valueOf(multiplier));try{return Long.valueOf(v.setScale(0).unscaledValue().longValueExact());}catch(ArithmeticException ex){return Double.valueOf(v.doubleValue());}}
}
